class MemoryInitialBindingSerializationTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:p");
	private static final IRI OBJECT = VF.createIRI("urn:o");
	private Repository repository;

	@BeforeEach
	void setUp() {
		repository = newMemoryRepository();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void injectsOneExactBindingAtTheStartOfTheOuterWhereClause() throws Exception {
		String query = "SELECT ?s WHERE { ?s <urn:p> <urn:o> }";
		MapBindingSet initialBindings = binding("s", VF.createBNode("fixed"));
		String serialized = withInitialBindings(query, initialBindings);

		int where = serialized.toUpperCase(Locale.ROOT).indexOf("WHERE");
		int openBrace = serialized.indexOf('{', where);
		assertTrue(where >= 0 && openBrace > where);
		assertTrue(serialized.substring(openBrace + 1).stripLeading().startsWith("VALUES"), serialized);
		List<BindingSetAssignment> assignments = new ArrayList<>();
		parse(serialized).getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment node) {
				assignments.add(node);
			}
		});
		assertEquals(1, assignments.size());
		Iterator<BindingSet> injectedBindings = assignments.get(0).getBindingSets().iterator();
		assertTrue(injectedBindings.hasNext());
		assertEquals(VF.createBNode("fixed"), injectedBindings.next().getValue("s"));
		assertFalse(injectedBindings.hasNext());

		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createBNode("fixed"), PREDICATE, OBJECT);
			List<BindingSet> rows = evaluate(connection, serialized);
			assertEquals(1, rows.size());
			assertEquals(VF.createBNode("fixed"), rows.get(0).getValue("s"));
		}
	}

	@Test
	void initialBnodeBindingWorksForSelectAskAndBound() throws Exception {
		BNode fixed = VF.createBNode("fixed");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(fixed, PREDICATE, OBJECT);

			List<BindingSet> selectRows = evaluate(connection,
					withInitialBindings("SELECT ?s WHERE { ?s <urn:p> <urn:o> }", binding("s", fixed)));
			assertEquals(1, selectRows.size());
			assertEquals(fixed, selectRows.get(0).getValue("s"));

			String ask = withInitialBindings("ASK { ?s <urn:p> <urn:o> }", binding("s", fixed));
			assertTrue(connection.prepareBooleanQuery(ask).evaluate());

			List<BindingSet> boundRows = evaluate(connection, withInitialBindings(
					"SELECT ?bound WHERE { BIND(BOUND(?b) AS ?bound) }", binding("b", fixed)));
			assertEquals(1, boundRows.size());
			assertEquals(VF.createLiteral(true), boundRows.get(0).getValue("bound"));
		}
	}

	@Test
	void predicateVariableRemainsVariableWhenItsInitialBindingIsAnIri() throws Exception {
		IRI otherPredicate = VF.createIRI("urn:q");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createBNode("selected"), PREDICATE, OBJECT);
			connection.add(VF.createBNode("other"), otherPredicate, OBJECT);
			String serialized = withInitialBindings("SELECT ?s ?p WHERE { ?s ?p ?o }", binding("p", PREDICATE));
			List<StatementPattern> patterns = new ArrayList<>();
			parse(serialized).getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(StatementPattern node) {
					patterns.add(node);
				}
			});
			assertEquals(1, patterns.size());
			assertEquals("p", patterns.get(0).getPredicateVar().getName());
			assertFalse(patterns.get(0).getPredicateVar().hasValue());

			List<BindingSet> rows = evaluate(connection, serialized);
			assertEquals(1, rows.size());
			assertEquals(VF.createBNode("selected"), rows.get(0).getValue("s"));
			assertEquals(PREDICATE, rows.get(0).getValue("p"));
		}
	}

	@Test
	void optionalMissingBoundSubjectIsRejectedAsUnsupportedTransport() {
		assertUnsupported("SELECT ?b ?o WHERE { OPTIONAL { ?b <urn:p> ?o } }", binding("b", VF.createBNode("missing")));
	}

	@Test
	void duplicateOriginalValuesRowsRemainDuplicateAfterInitialBindingInjection() throws Exception {
		BNode fixed = VF.createBNode("fixed");
		try (RepositoryConnection connection = repository.getConnection()) {
			String query = "SELECT ?b WHERE { VALUES ?b { <_:fixed> <_:fixed> } }";
			List<BindingSet> rows = evaluate(connection, withInitialBindings(query, binding("b", fixed)));
			assertEquals(2, rows.size());
			assertTrue(rows.stream().allMatch(row -> fixed.equals(row.getValue("b"))));
		}
	}

	@Test
	void variablesInsideLiteralsCommentsAndIrisRemainUntouched() throws Exception {
		String query = "SELECT ?text ?iri WHERE {\n"
				+ "  BIND(\"?b\" AS ?text) # ?b in a comment must stay text\n"
				+ "  VALUES ?iri { <urn:question?b> }\n"
				+ "}";
		String serialized = withInitialBindings(query, binding("b", VF.createBNode("fixed")));
		assertTrue(serialized.contains("BIND(\"?b\" AS ?text) # ?b in a comment must stay text"), serialized);
		assertTrue(serialized.contains("<urn:question?b>"), serialized);

		try (RepositoryConnection connection = repository.getConnection()) {
			List<BindingSet> rows = evaluate(connection, serialized);
			assertEquals(1, rows.size());
			assertEquals(VF.createLiteral("?b"), rows.get(0).getValue("text"));
			assertEquals(VF.createIRI("urn:question?b"), rows.get(0).getValue("iri"));
		}
	}

	@Test
	void unsafeBindingScopesAreRejectedAsUnsupportedTransport() {
		MapBindingSet bnode = binding("b", VF.createBNode("fixed"));
		assertUnsupported("SELECT ?b WHERE { BIND(<urn:other> AS ?b) }", bnode);
		assertUnsupported("SELECT (?s AS ?b) WHERE { ?s <urn:p> ?o }", bnode);
		assertUnsupported("SELECT ?s (COUNT(*) AS ?b) WHERE { ?s <urn:p> ?o } GROUP BY ?s", bnode);
		assertUnsupported("SELECT ?x WHERE { { SELECT ?x WHERE { ?x <urn:p> ?o } } }",
				binding("x", VF.createBNode("fixed")));
		assertUnsupported("SELECT ?b WHERE { { SELECT ?b WHERE { ?s <urn:p> ?o } } }", bnode);
		assertUnsupported("CONSTRUCT WHERE { ?s ?p ?o }", binding("s", VF.createBNode("fixed")));
		assertUnsupported("SELECT ?o WHERE { SERVICE <urn:service> { ?s <urn:p> ?o } }",
				binding("s", VF.createBNode("fixed")));
	}

	private static void assertUnsupported(String query, BindingSet bindings) {
		UnsupportedOperationException failure = assertThrows(UnsupportedOperationException.class,
				() -> withInitialBindings(query, bindings));
		String message = String.valueOf(failure.getMessage()).toLowerCase(Locale.ROOT);
		assertTrue(message.contains("unsupported") || message.contains("not supported")
				|| message.contains("cannot safely"), "unsupported binding transport must be explicit: " + failure);
	}

	private static MapBindingSet binding(String name, Value value) {
		MapBindingSet result = new MapBindingSet();
		result.addBinding(name, value);
		return result;
	}

	private static Repository newMemoryRepository() {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		return repository;
	}

	private static List<BindingSet> evaluate(RepositoryConnection connection, String query) {
		List<BindingSet> results = new ArrayList<>();
		try (TupleQueryResult rows = connection.prepareTupleQuery(query).evaluate()) {
			while (rows.hasNext()) {
				results.add(rows.next());
			}
		}
		return results;
	}

	private static ParsedQuery parse(String query) {
		return new SPARQLParser().parseQuery(query, null);
	}

	private static String withInitialBindings(String query, BindingSet bindings) {
		try {
			Method helper = SPARQLQueries.class.getMethod("withInitialBindings", String.class, BindingSet.class);
			return (String) helper.invoke(null, query, bindings);
		} catch (NoSuchMethodException e) {
			throw new AssertionError("Missing public SPARQLQueries.withInitialBindings(String, BindingSet)", e);
		} catch (InvocationTargetException e) {
			Throwable cause = e.getCause();
			if (cause instanceof RuntimeException runtimeException) {
				throw runtimeException;
			}
			if (cause instanceof Error error) {
				throw error;
			}
			throw new AssertionError("Initial-binding serializer failed", cause);
		} catch (ReflectiveOperationException e) {
			throw new AssertionError("Could not invoke the public initial-binding serializer", e);
		}
	}
}
